warnings.plsql:
declare
  l_msg varchar2(4000);
begin
  for x in (select d.item_code, (((select nvl(sum(o.quantity), 0) from pr_order_det o where o.group_code = d.group_code and o.item_code = d.item_code) - (select nvl(sum(nvl(ld.income_quantity, 0)), 0) from pr_income_lot_det ld, pr_income_lot lm where ld.trns_type_code = lm.trns_type_code and ld.trns_serial = lm.trns_serial and ld.group_code = d.group_code and ld.item_code = d.item_code))) q from pr_order_request m, pr_order_det_request d
             where m.rowid = chartorowid(:PAGE_ROWID) and d.TRNS_TYPE_CODE = m.TRNS_TYPE_CODE and d.TRNS_SERIAL = m.TRNS_SERIAL
               and not exists (select 1 from pr_order_det_request as of timestamp (systimestamp - interval '2' second) o where o.rowid = d.rowid and o.item_code = d.item_code)) loop
    if nvl(x.q, 0) > 0 then
      l_msg := l_msg || case when v('G_LANG') = 'en' then 'There is a quantity ' || x.q || ' of item ' || x.item_code || ' not received yet'
                        else 'هناك كمية ' || x.q || ' من الصنف ' || x.item_code || ' لم يتم إستلامها' end || chr(10);
    end if;
  end loop;
  return rtrim(l_msg, chr(10));
exception when others then return null;
end;
